def leadCaptures_sp(json_file: dict):
    conn = None
    try:
        conn = connection()
        cursor = conn.cursor()

        payload_list = json_file.get("leadCaptures", [])
        if not payload_list:
            return JSONResponse(content={
                "error": "Invalid payload format. Expected {'leadCaptures': [{...}]}"
            }, status_code=400)

        payload = payload_list[0]
        action = payload.get("action")

        if action == 1:  # INSERT
            # ADR-001: Public submission endpoint must not read, accept, default, or validate against a client-supplied companyId.
            # Also must not accept status, assignedTo, created_At, updated_at from the client.
            # The SP is expected to handle setting these values (companyId=default, status='new', timestamps).
            filtered_payload = {k: v for k, v in payload.items() if k not in [
                "companyId", "status", "assignedTo", "created_At", "updated_at"
            ]}

            # Constraint: Must reject requests where privacyConsentAccepted is not true.
            if not filtered_payload.get("privacyConsentAccepted"): # Assumes client sends as boolean
                return JSONResponse(content={
                    "error": "Privacy consent must be accepted to submit a lead."
                }, status_code=400)

            # Reconstruct json_file with filtered payload for the SP call
            json_to_pass = {"leadCaptures": [filtered_payload]}
        else:
            # For UPDATE (2) and DELETE (3), companyId and other internal fields are expected from authenticated users.
            json_to_pass = json_file

        cursor.execute("EXEC [dbo].[sp_leadCaptures] @pjsonfile = %s", (json.dumps(json_to_pass),))
        # Upsert SP returns ONE row, ONE column -- use fetchone()[0]
        row = cursor.fetchone()
        json_result = row[0] if row and row[0] else '{"message": "ok"}'

        result_dict = json.loads(json_result)

        # ADR-002: Inspect SP's embedded result.error field for duplicate rejection
        if result_dict.get("error"): # SP should return an error if email is a duplicate
            # Return non-2xx status for duplicate rejection as per backend constraint.
            # 409 Conflict is appropriate for duplicate resource.
            return JSONResponse(content=result_dict, status_code=409)

        # Log audit for mutations (action=2/UPDATE, action=3/DELETE)
        if action in [2, 3]:
            entity_id = payload.get("leadCaptureId")
            if entity_id:
                # This is a simplified audit, capturing the action. A full audit would involve fetching the before-image.
                log_audit(
                    entity="leadCapture",
                    entity_id=str(entity_id),
                    field="action_type",
                    old_value=None,
                    new_value="update" if action == 2 else "delete",
                    action=action
                )

        return JSONResponse(content=result_dict, status_code=200)
    except Exception as e:
        # PII constraint: Personal/contact information must not appear in application or error logs in plaintext.
